<script>const providerRows=[...document.querySelectorAll('.provider-row')];providerRows.forEach(row=>{row.draggable=true;row.title='Drag to change fallback priority';row.addEventListener('dragstart',()=>row.classList.add('dragging'));row.addEventListener('dragend',()=>{row.classList.remove('dragging');[...document.querySelectorAll('.provider-row .badge')].forEach((b,i)=>b.textContent=i+1)});row.addEventListener('dragover',event=>{event.preventDefault();const dragging=document.querySelector('.provider-row.dragging');if(!dragging||dragging===row)return;const box=row.getBoundingClientRect();row.parentNode.insertBefore(dragging,event.clientY<box.top+box.height/2?row:row.nextSibling)})});</script>
